import json, re
from pathlib import Path

PAT = re.compile(r"^<<<<<<< HEAD[^\n]*\n(.*?)^=======[^\n]*\n(.*?)^>>>>>>>[^\n]*\n?", re.S | re.M)

def split_sides(text):
    def clean(s):
        return "<<<<<<<" not in s and "=======" not in s and ">>>>>>>" not in s
    ours = PAT.sub(lambda m: m.group(1), text)
    theirs = PAT.sub(lambda m: m.group(2), text)
    assert clean(ours) and clean(theirs)
    return ours, theirs

# Generated docs - take theirs (regenerated by tools).
for f in ["docs/EVIDENCE_REFERENCE_AUDIT.md", "docs/TASK_QUEUE.md"]:
    p = Path(f)
    ours, theirs = split_sides(p.read_text(encoding="utf-8"))
    p.write_text(theirs, encoding="utf-8")
    print(f, "kept theirs")

# transcription_audit.py - HEAD side should hold all checks incl. my unit.
p = Path("scripts/ci/transcription_audit.py")
text = p.read_text(encoding="utf-8")
ours = PAT.sub(lambda m: m.group(1), text)
theirs = PAT.sub(lambda m: m.group(2), text)
q = json.loads(Path("build/task_queue.json").read_text(encoding="utf-8"))
uid = "NORM|35c971a0758598e57593706d43c4732904e25dab80fb92770430a30ab0f83d3f"
needle = next(x for x in q["tasks"] if x.get("normative_id") == uid)["text"]
nl = json.dumps(needle, ensure_ascii=True)
# Prefer the side containing my check; prefer theirs if both (main has newer checks).
if nl in theirs:
    s = theirs
else:
    s = ours
assert nl in s, "my audit check missing"
p.write_text(s, encoding="utf-8")
assert "<<<<<<<" not in p.read_text(encoding="utf-8")
print("audit resolved; my check present:", nl in s)
